package finance.client;
import finance.network.RegionalRiskResponsePacket;import java.util.concurrent.atomic.AtomicLong;
public final class RegionalRiskClientCache{public enum State{NOT_REQUESTED,LOADING,READY,SLOW}public record Entry(State state,long requestId,long at,RegionalRiskResponsePacket data){}private static final AtomicLong SEQ=new AtomicLong();private static Entry entry=new Entry(State.NOT_REQUESTED,0,0,null);private RegionalRiskClientCache(){}public static long begin(){long id=SEQ.updateAndGet(v->v==Long.MAX_VALUE?1:v+1);entry=new Entry(State.LOADING,id,System.currentTimeMillis(),null);return id;}public static void accept(RegionalRiskResponsePacket p){if(p!=null&&p.requestId()==entry.requestId())entry=new Entry(State.READY,p.requestId(),0,p);}public static Entry get(){if(entry.state()==State.LOADING&&System.currentTimeMillis()-entry.at()>3000)entry=new Entry(State.SLOW,entry.requestId(),entry.at(),null);return entry;}public static void clear(){entry=new Entry(State.NOT_REQUESTED,0,0,null);}}
